SELECT 'CATEGORY' AS kind, id, code, status, sort_order FROM platform_categories WHERE code LIKE 'LIVE-CAT-%' ORDER BY created_at DESC LIMIT 1;
SELECT 'ITEM' AS kind, i.id, i.stable_code, i.status, v.version_no, v.status AS version_status FROM platform_items i JOIN platform_item_versions v ON v.item_id=i.id WHERE i.stable_code LIKE 'LIVE-ITEM-%' ORDER BY i.created_at DESC LIMIT 1;
SELECT 'EVIDENCE_RULES' AS kind, COUNT(*) AS n FROM platform_evidence_rules er JOIN platform_item_versions v ON v.id=er.item_version_id JOIN platform_items i ON i.id=v.item_id WHERE i.stable_code = (SELECT stable_code FROM platform_items WHERE stable_code LIKE 'LIVE-ITEM-%' ORDER BY created_at DESC LIMIT 1);
SELECT 'ISSUE_FIELDS' AS kind, field_code, input_type FROM platform_issue_fields f JOIN platform_item_versions v ON v.id=f.item_version_id JOIN platform_items i ON i.id=v.item_id WHERE i.stable_code = (SELECT stable_code FROM platform_items WHERE stable_code LIKE 'LIVE-ITEM-%' ORDER BY created_at DESC LIMIT 1);
SELECT 'MEASUREMENT_BANDS' AS kind, field_code, unit_code, direction, min_value, max_value, result_code FROM platform_measurement_bands mb JOIN platform_item_versions v ON v.id=mb.item_version_id JOIN platform_items i ON i.id=v.item_id WHERE i.stable_code = (SELECT stable_code FROM platform_items WHERE stable_code LIKE 'LIVE-ITEM-%' ORDER BY created_at DESC LIMIT 1);
SELECT 'OPTION_SET' AS kind, id, code, status FROM platform_option_sets WHERE code LIKE 'LIVE-SET-%' ORDER BY created_at DESC LIMIT 1;
SELECT 'TEMPLATE' AS kind, id, code, status, version_no, version_status FROM (SELECT t.id, t.code, t.status, tv.version_no, tv.status AS version_status FROM platform_templates t JOIN platform_template_versions tv ON tv.template_id=t.id WHERE t.code LIKE 'LIVE-TPL-%' ORDER BY t.created_at DESC LIMIT 1) x;
SELECT 'TEMPLATE_CATEGORIES' AS kind, COUNT(*) AS n FROM platform_template_categories tc JOIN platform_template_versions tv ON tv.id=tc.template_version_id JOIN platform_templates t ON t.id=tv.template_id WHERE t.code = (SELECT code FROM platform_templates WHERE code LIKE 'LIVE-TPL-%' ORDER BY created_at DESC LIMIT 1);
SELECT 'TEMPLATE_ITEMS' AS kind, COUNT(*) AS n FROM platform_template_items ti JOIN platform_template_versions tv ON tv.id=ti.template_version_id JOIN platform_templates t ON t.id=tv.template_id WHERE t.code = (SELECT code FROM platform_templates WHERE code LIKE 'LIVE-TPL-%' ORDER BY created_at DESC LIMIT 1);
SELECT 'LEGACY_SCORING_ROWS_RETAINED_FOR_LATER_PHASES' AS kind, (SELECT COUNT(*) FROM platform_scoring_rules) + (SELECT COUNT(*) FROM platform_grade_boundaries) AS n;

